<?php
declare(strict_types=1);
require_once __DIR__ . '/config/database.php';
$pdo = srnu_db();
if (isset($_GET['ping'])) { header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok'=>true,'servicio'=>'firma','hora'=>date('Y-m-d H:i:s')], JSON_UNESCAPED_UNICODE); exit; }
$token = trim((string)($_GET['token'] ?? $_POST['token'] ?? ''));
if (!preg_match('/^[a-f0-9]{64}$/', $token)) { http_response_code(404); exit('Enlace de firma no válido.'); }
$stmt=$pdo->prepare('SELECT * FROM firmas_digitales WHERE token=? LIMIT 1');$stmt->execute([$token]);$firma=$stmt->fetch();
if(!$firma){http_response_code(404);exit('Enlace de firma no encontrado.');}
$c=srnu_obtener_cotizacion((int)$firma['cotizacion_id']);if(!$c){http_response_code(404);exit('Cotización no encontrada.');}
$currentHash=srnu_hash_cotizacion_para_firma($c);
$enlaceVigente=hash_equals((string)$firma['snapshot_hash'],$currentHash);
$error='';$exito=false;
if($_SERVER['REQUEST_METHOD']==='POST' && ($firma['estado']??'')==='pendiente'){
    if(!$enlaceVigente){$error='La cotización cambió después de generar este enlace. Solicita un enlace nuevo al taller.';}
    else{
        $nombre=trim((string)($_POST['nombre_firmante']??''));$acepto=!empty($_POST['acepto']);$data=(string)($_POST['firma_data']??'');
        if($nombre==='')$error='Escribe el nombre de la persona que firma.';
        elseif(!$acepto)$error='Debes aceptar los conceptos y condiciones para firmar.';
        elseif(!preg_match('#^data:image/png;base64,([A-Za-z0-9+/=]+)$#',$data,$m))$error='La firma no pudo leerse. Vuelve a dibujarla.';
        else{
            $raw=base64_decode($m[1],true);
            if($raw===false || strlen($raw)<150 || strlen($raw)>1500000)$error='La firma está vacía o es demasiado grande.';
            else{
                $at=date('Y-m-d H:i:s');$ip=(string)($_SERVER['REMOTE_ADDR']??'');$ua=substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,500);
                $verify=hash('sha256',$currentHash.'|'.$nombre.'|'.$at.'|'.$data);
                $upd=$pdo->prepare("UPDATE firmas_digitales SET estado='firmada',nombre_firmante=?,firma_data=?,acepto=1,firmado_at=?,ip_firmante=?,user_agent=?,hash_verificacion=?,updated_at=NOW() WHERE id=? AND estado='pendiente'");
                $upd->execute([$nombre,$data,$at,$ip,$ua,$verify,(int)$firma['id']]);
                $pdo->prepare("UPDATE cotizaciones SET aceptada_at=COALESCE(aceptada_at,NOW()), estado=CASE WHEN estado='Cotización' THEN 'Aprobada' ELSE estado END WHERE id=?")->execute([(int)$c['id']]);
                $stmt->execute([$token]);$firma=$stmt->fetch();$exito=true;
            }
        }
    }
}
$yaFirmada=($firma['estado']??'')==='firmada';
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Firmar · <?=htmlspecialchars($c['cliente'].' · '.$c['vehiculo'],ENT_QUOTES,'UTF-8')?></title><link rel="icon" href="favicon.png"><style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:#f3f6fb;color:#0f172a}.top{background:#080b12;color:#fff;padding:16px}.topin{max-width:820px;margin:auto;display:flex;align-items:center;gap:12px}.top img{width:38px;height:38px;object-fit:contain}.top b{font-size:16px}.top span{display:block;font-size:12px;color:#94a3b8;margin-top:2px}.wrap{max-width:820px;margin:24px auto;padding:0 14px 40px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:20px;box-shadow:0 12px 40px rgba(15,23,42,.08);padding:22px;margin-bottom:14px}h1{font-size:28px;margin:0 0 5px}h2{font-size:18px;margin:0 0 14px}.muted{color:#64748b;font-size:13px}.facts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.fact{padding:12px;background:#f8fafc;border-radius:12px}.fact small{display:block;color:#64748b;font-size:11px}.fact strong{display:block;margin-top:4px}.items{width:100%;border-collapse:collapse}.items td{padding:10px 5px;border-bottom:1px solid #eef2f7;font-size:13px}.items td:last-child{text-align:right;font-weight:800}.total{font-size:26px;font-weight:900;text-align:right;margin-top:14px}.signbox{border:2px dashed #94a3b8;border-radius:14px;background:#fff;overflow:hidden;touch-action:none}.signbox canvas{width:100%;height:220px;display:block;touch-action:none}.field{display:block;margin:14px 0 6px;font-size:12px;font-weight:800}.input{width:100%;padding:13px;border:1px solid #cbd5e1;border-radius:11px;font:inherit}.accept{display:flex;gap:10px;align-items:flex-start;margin:15px 0;padding:13px;border-radius:12px;background:#f8fafc}.accept input{width:20px;height:20px;accent-color:#2563eb;margin-top:1px}.btns{display:flex;gap:10px;justify-content:flex-end}.btn{border:0;border-radius:11px;padding:12px 16px;font-weight:850;cursor:pointer}.primary{background:#2563eb;color:#fff}.light{background:#e2e8f0;color:#0f172a}.ok{background:#dcfce7;color:#166534;border:1px solid #86efac;padding:16px;border-radius:14px}.bad{background:#fee2e2;color:#991b1b;border:1px solid #fecaca;padding:14px;border-radius:12px}.sigimg{width:min(420px,100%);height:150px;object-fit:contain;border:1px solid #e2e8f0;border-radius:12px;background:#fff}@media(max-width:600px){.facts{grid-template-columns:1fr}.card{padding:17px}.btns{flex-direction:column-reverse}.btn{width:100%}h1{font-size:23px}}
</style></head><body><header class="top"><div class="topin"><img src="favicon.png" alt="SRNU"><div><b>SRNU CUSTOM</b><span>Aceptación digital de cotización</span></div></div></header><main class="wrap">
<section class="card"><h1><?=htmlspecialchars($c['cliente'],ENT_QUOTES,'UTF-8')?></h1><p class="muted">Revisa la información antes de firmar.</p><div class="facts"><div class="fact"><small>Folio</small><strong><?=htmlspecialchars($c['folio'],ENT_QUOTES,'UTF-8')?></strong></div><div class="fact"><small>Vehículo</small><strong><?=htmlspecialchars($c['vehiculo'],ENT_QUOTES,'UTF-8')?></strong></div><div class="fact"><small>Fecha</small><strong><?=htmlspecialchars($c['fecha'],ENT_QUOTES,'UTF-8')?></strong></div><div class="fact"><small>Modalidad</small><strong><?=$c['requiere_factura']==='si'?'Con factura':'Sin factura'?></strong></div></div></section>
<?php $tgMin=(int)($c['dias_trabajo_general_min']??0);$tgMax=(int)($c['dias_trabajo_general_max']??0);$tienePedido=false;foreach(($c['items']??[]) as $ti){if(($ti['tipo_entrega']??'inmediata')==='sobre_pedido'){$tienePedido=true;break;}}if($tgMin>0||$tgMax>0):?>
<section class="card"><h2>Tiempo estimado de trabajo</h2><p style="margin:0"><strong><?=$tgMin>0&&$tgMax>0?($tgMin.' a '.$tgMax):($tgMax?:$tgMin)?> días</strong><?php if($tienePedido):?>, contados una vez recibidas <strong>todas las piezas necesarias</strong> en el taller.<?php else:?> de trabajo total estimado para el vehículo.<?php endif;?></p><p class="muted" style="margin-bottom:0">El plazo puede variar por el alcance final del trabajo y las condiciones del vehículo.</p></section>
<?php endif;?>
<section class="card"><h2>Conceptos</h2><table class="items"><?php foreach($c['items'] as $it):?><tr><td><?=htmlspecialchars((string)$it['concepto'],ENT_QUOTES,'UTF-8')?><div class="muted"><?=number_format((float)$it['cantidad'],2)?> × $<?=number_format((float)$it['precio'],2)?></div></td><td>$<?=number_format((float)$it['total'],2)?></td></tr><?php endforeach;?></table><div class="total">Total: $<?=number_format((float)$c['total'],2)?></div></section>
<?php if(!$enlaceVigente):?><section class="card"><div class="bad"><b>Este enlace ya no corresponde a la versión actual de la cotización.</b><br>El taller debe generar un enlace nuevo antes de firmar.</div></section>
<?php elseif($yaFirmada):?><section class="card"><div class="ok"><b>✓ Cotización firmada correctamente</b><br>La aceptación quedó registrada el <?=htmlspecialchars((string)$firma['firmado_at'],ENT_QUOTES,'UTF-8')?>.</div><?php if(!empty($firma['firma_data'])):?><p><img class="sigimg" src="<?=htmlspecialchars((string)$firma['firma_data'],ENT_QUOTES,'UTF-8')?>" alt="Firma"></p><?php endif;?><p class="muted">Firmante: <?=htmlspecialchars((string)$firma['nombre_firmante'],ENT_QUOTES,'UTF-8')?> · Verificación: <?=htmlspecialchars(substr((string)$firma['hash_verificacion'],0,16),ENT_QUOTES,'UTF-8')?></p></section>
<?php else:?><section class="card"><h2>Firma de aceptación</h2><?php if($error):?><div class="bad"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><form method="post" id="sign-form"><input type="hidden" name="token" value="<?=htmlspecialchars($token,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="firma_data" id="firma-data"><label class="field">Nombre completo de quien firma</label><input class="input" name="nombre_firmante" required maxlength="180" value="<?=htmlspecialchars((string)($_POST['nombre_firmante']??$c['cliente']),ENT_QUOTES,'UTF-8')?>"><label class="field">Firma</label><div class="signbox"><canvas id="pad"></canvas></div><div class="btns" style="margin-top:9px"><button class="btn light" type="button" id="clear">Borrar firma</button></div><label class="accept"><input type="checkbox" name="acepto" value="1" required><span>He revisado esta cotización y <b>acepto los conceptos, importes y condiciones indicadas</b>. Confirmo que la firma dibujada corresponde a mi aceptación.</span></label><div class="btns"><button class="btn primary" type="submit">Firmar y aceptar cotización</button></div></form></section><?php endif;?>
<p class="muted" style="text-align:center">SRNU Custom · Modificación Automotriz</p></main>
<?php if(!$yaFirmada && $enlaceVigente):?><script>
(function(){const c=document.getElementById('pad'),ctx=c.getContext('2d'),form=document.getElementById('sign-form'),out=document.getElementById('firma-data');let drawing=false,hasInk=false,last=null;
function resize(){const r=c.getBoundingClientRect(),d=Math.max(1,window.devicePixelRatio||1),old=hasInk?c.toDataURL('image/png'):null;c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);ctx.lineWidth=2.3;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#0f172a';if(old){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0,r.width,r.height);im.src=old}}
function pt(e){const r=c.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:p.clientX-r.left,y:p.clientY-r.top}}
function start(e){e.preventDefault();drawing=true;last=pt(e)}function move(e){if(!drawing)return;e.preventDefault();const p=pt(e);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p;hasInk=true}function end(){drawing=false;last=null}
['mousedown','touchstart'].forEach(x=>c.addEventListener(x,start,{passive:false}));['mousemove','touchmove'].forEach(x=>c.addEventListener(x,move,{passive:false}));['mouseup','mouseleave','touchend','touchcancel'].forEach(x=>c.addEventListener(x,end));document.getElementById('clear').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);hasInk=false};form.addEventListener('submit',e=>{if(!hasInk){e.preventDefault();alert('Dibuja tu firma antes de continuar.');return}out.value=c.toDataURL('image/png')});window.addEventListener('resize',resize);resize()})();
</script><?php endif;?></body></html>
